/**
 * @method
 * @name setHeader
 * @description 메일 마스터(dts_Master)·수신자(dts_Receiver)·첨부파일(dts_fileData) 데이터셋 헤더를 초기 조회/구성한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.setHeader();
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_Master",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Master=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    dts_Master.addRow();
    const sbmOptions2 = {
        id : "sbm_dts_Receiver",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Receiver=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);

    // 파일: 가우스헤더 셋팅	

    // TODO Stage2: Gauce 통신(DataID/KeyValue/Post/SetDataHeader) — executeDynamic 재설계 필요(규칙 12/16)
    dts_fileData.SetDataHeader("fileInfo:String,fileUrl:URL,FILE_NAME:String,FILE_SIZE:String,FILE_SEQ:String,NOTI_SVC_ID:String" + ",FILE_SIZE_VIEW:String");
    const sbmOptions3 = {
        id : "sbm_dts_fileData",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_fileData=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);

    // dts_fileData.AddRow();	

};

/**
 * @method
 * @name setData
 * @description 보낸이·보낸이 이메일·비밀참조수신을 '기술상장심사'/'krxtechlisting@krx.co.kr' 기본값으로 설정한다.
 * @returns {void}
 * @hidden N
 * @example scwin.setData();
 */
scwin.setData = function() {
    txb_fromName.setValue("기술상장심사");
    txb_fromEmail.setValue("krxtechlisting@krx.co.kr");
    txb_BccName.setValue("기술상장심사");
    txb_BccEmail.setValue("krxtechlisting@krx.co.kr");
};

/**
 * @method
 * @name initPage
 * @description 호출 URL 파라미터(NOTI_SVC_ID/ADD_INPUT/frameID)를 수신하고, 추가입력 여부에 따라 기존 메일 조회(read) 또는 신규 헤더 구성(setHeader) 후 기본값을 설정한다.
 * @returns {void}
 * @hidden N
 * @example scwin.initPage();
 */
scwin.initPage = function() {
    scwin.gNOTI_SVC_ID = $c.stf.getQuery(frame.srcUrl, "NOTI_SVC_ID");
    scwin.gAddInput = $c.stf.getQuery(frame.srcUrl, "ADD_INPUT");
    scwin.gPvd = $c.stf.getQuery(frame.srcUrl, "frameID");
    // alert('[gPvd]'+gPvd);
    // alert('[gNOTI_SVC_ID]'+gNOTI_SVC_ID);
    // alert('[gAddInput]'+gAddInput);
    if (scwin.gAddInput === 'Y') {
        scwin.read();
        scwin.setData();
    } else {
        scwin.setHeader();
        scwin.setData();
    }
};

/**
