        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    // alert(url);
    const sbmOptions2 = {
        id : "sbm_dts_fileData",
        action : "/EmailMgt.do",
        ref : "",
        target : "dts_fileData=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);

    const sbmOptions3 = {
        id : "sbm_dts_Receiver",
        action : "/EmailMgt.do",
        ref : "",
        target : "dts_Receiver=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);

};

/**
 * @method
 * @name fn_filedown
 * @description 첨부파일 다운로드 — 알림서비스ID·첨부순번으로 파일 다운로드 URL로 이동한다.
 * @param {String} vNotiSvcId 알림서비스 ID
 * @param {String} vSeq 첨부파일 순번
 * @returns {void}
 * @hidden N
 * @example $c.en.fn_filedown(vNotiSvcId, vSeq);
 */
$c.en.fn_filedown = function(vNotiSvcId, vSeq) {
    // var vNotiSvcId= getObjectValue(txb_NOTI_SVC_ID);
    // var vSeq= getObjectValue(txb_file_seq);

    const link = "/filedownload.do?NOTI_SVC_ID=" + vNotiSvcId + "&SEQ=" + vSeq + "&gubun=11";
    location.href = encodeURI(link);
};

