    panel_debug.hide();
    // showObj(panel_BCC, false);

};

/**
 * @method
 * @name registerMail
 * @description 입력값·파일용량 검증 후 전송 확인을 거쳐 전문평가 메일 발송 트랜잭션(trs_Save)을 실행한다.
 * @returns {void}
 * @hidden N
 * @example scwin.registerMail();
 */
scwin.registerMail = function() {
    // alert_parse(dts_Receiver.Text, ",");return;
    if (scwin.fn_CheckForm() && scwin.checkFileSize()) {
        const msg = $c.stf.getMessageParam("MSG-A006", "전송");
        const res = window.confirm(msg);
        if (res) {
            const url = "/EmailMgt.do?method=sendSpecyValuEmail" + "&SCREN_ID=" + "ULDSTF07404.gfm" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            // alert(dts_MASTER.Text);
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            // TODO Stage2: Gauce 통신(DataID/KeyValue/Post) — executeDynamic 재설계 필요(규칙 12/16)
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Master, I:pInputDetail=dts_Receiver, I:pFile=dts_fileData)";

            trs_Save.post();
        }
    }
};

/**
 * @method
 * @name checkFileSize
 * @description 전체 파일 사이즈 체크 — 첨부파일 합계가 제한(30MB)을 초과하면 경고 후 false를 반환한다.
 * @returns {Boolean} 파일용량 유효 여부
 * @hidden N
 * @example if (scwin.checkFileSize()) { scwin.registerMail(); }
 */
scwin.checkFileSize = function() {
    let totalFileSize = 0;
    let isValid = true;
    for (let i = 1; i <= dts_fileData.CountRow; i++) {

        totalFileSize = Number(totalFileSize) + Number(dts_fileData.getCellData(i, "FILE_SIZE"));
    }
    if (totalFileSize > scwin.fileSizeLimit) {
        alert("전체 파일용량은 30MB를 초과할 수 없습니다");
        isValid = false;
    }
    return isValid;
};

/**
 * @method
 * @name fn_CheckForm
 * @description 메일 발송 전 유효성 체크 — 보낸이 이메일 형식, 제목·내용 필수값, 수신자 선택 여부를 검사한다(개발환경이면 발송 주의 알림).
 * @returns {Boolean} 검증 통과 여부
 * @hidden N
 * @example if ($c.en.fn_CheckForm()) { scwin.registerMail(); }
 */
$c.en.fn_CheckForm = function() {
    let msg = "";
    if ($c.ut.email_chk(txb_fromEmail.getValue()) === false) {
        alert("잘못된 이메일 주소입니다.");

        txb_fromEmail.focus();
        return false;
    }
    if (txb_title.getValue() === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "제목");
        alert(msg);

        txb_title.focus();
        return false;
    }
    if (txa_content.getValue() === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "내용");
        alert(msg);

        txa_content.focus();
        return false;
    }
    /*
    if (getObjectValue(txb_EMP_NO) == "")	{
    	alert("세션정보를 받지 못했읍니다.");

    	txb_EMP_NO.focus();
    	return false;
    }
    */
    // dts_Receiver 에서 CHECK 된 걸 찾는다.
    let total = 0;
    for (let i = 0; i <= dts_Receiver.CountRow; i++) {

        const chk = dts_Receiver.getCellData(i, "CHECK");
        if (chk === "T" || chk === "1") {
            total++;
        }
    }
    if (total === 0) {
        alert("선택된 수신자가 없습니다.");
        return false;
    }
    if (js_svrGubun === 'local' || js_svrGubun === 'dev' || js_svrGubun === 'test1' || js_svrGubun === 'test2') {
        alert("◆ 주의 사항 ◆\n\n개발환경에서도 메일이 발송되므로 수신자 메일주소를 확인바랍니다.");
    }
    return true;
};

/**
 * @method
 * @name cancel
 * @description [취소] 처리 — 작성한 내용을 초기화(헤더 재구성·기본값 설정)하고 첨부파일 목록을 비운다.
 * @returns {void}
 * @hidden N
 * @example scwin.cancel();
 */
scwin.cancel = function() {
    scwin.setHeader();
    scwin.setData();

    dts_fileData.removeAll();
};

/**
 * @method
 * @name selectAll
 * @description [전체선택]/[전체해제] 토글 — 담당자(dts_Receiver) 선택 체크박스를 전체선택 또는 전체해제하고 버튼 라벨을 갱신한다.
 * @returns {void}
 * @hidden N
 * @example scwin.selectAll();
 */
scwin.selectAll = function() {
    if (scwin.gAllChk === false) {
        // 현재상태가 false이면 전체선택을 클릭릭한것

        scwin.gAllChk = true;
        for (let i = 0; i < dts_Receiver.CountRow; i++) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            /*ORG SRC: dts_Receiver.NameString(i + 1, "CHECK") = "T";*/
            X = "T";
        }
        btn_SelectedAll.setValue("전체해제");
    } else {
        // 현재상태가  true이면 전체선택을 클릭한것
        scwin.gAllChk = false;
        for (let i = 0; i < dts_Receiver.CountRow; i++) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            /*ORG SRC: dts_Receiver.NameString(i + 1, "CHECK") = "F";*/
            X = "F";
        }
        btn_SelectedAll.setValue("전체선택");
    }
};

