/**
 * @method
 * @name formatBytes
 * @description 바이트 수를 단위(Bytes/KB/MB/GB) 문자열로 변환한다.
 * @param {Number} bytes 바이트 수
 * @returns {String} 단위 표기 문자열
 * @hidden N
 * @example scwin.formatBytes(1048576); // "1 MB"
 */
scwin.formatBytes = function(bytes) {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];

    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
};

